import pytest

from sales_dashboard.loader import daily_conversion_counts, dedupe_sessions, parse_session_log
from sales_dashboard.metrics import (
    conversion_rate,
    conversion_rate_by_group,
    conversions_in_window,
    longest_conversion_streak,
    pooled_conversion_rate,
)
from sales_dashboard.report import campaign_summary, top_converting_groups


def test_conversion_rate_basic():
    assert conversion_rate([{"converted": True}, {"converted": False}]) == 0.5


def test_pooled_conversion_rate_equal_groups():
    groups = {"a": [{"converted": True}, {"converted": False}], "b": [{"converted": True}, {"converted": False}]}
    assert pooled_conversion_rate(groups) == 0.5


def test_parse_session_log_one_line():
    assert parse_session_log(["x1,3,1"]) == [{"id": "x1", "day": 3, "converted": True}]


def test_campaign_summary_basic():
    e = [{"id": "a", "day": 1, "converted": True}, {"id": "b", "day": 2, "converted": False}]
    assert campaign_summary({"g": e}, 1) == {"rate": 0.5, "recent": 0, "groups": 1}


def test_conversion_rate_counts_none_as_not_converted():
    assert conversion_rate([{"converted": True}, {"converted": None}]) == 0.5


def test_conversion_rate_empty():
    assert conversion_rate([]) == 0.0


def test_pooled_conversion_rate_weights_sessions_not_groups():
    groups = {
        "one": [{"converted": True}],
        "two": [{"converted": False}, {"converted": None}],
        "empty": [],
    }
    assert pooled_conversion_rate(groups) == 1 / 3
    assert pooled_conversion_rate({"empty": []}) == 0.0


@pytest.mark.parametrize(("days", "expected"), [(0, 0), (2, 7), (10, 9)])
def test_conversions_in_window(days, expected):
    assert conversions_in_window([2, 3, 4], days) == expected


def test_parse_session_log_skips_blanks_and_comments_and_trims_fields():
    lines = ["", " \t\n", "  # comment", " a , 1 , 1 ", " b , 2 , 0 ", " c , 3 ,  "]
    assert parse_session_log(lines) == [
        {"id": "a", "day": 1, "converted": True},
        {"id": "b", "day": 2, "converted": False},
        {"id": "c", "day": 3, "converted": None},
    ]


@pytest.mark.parametrize("invalid", ["a,3", "a,3,1,extra", "a,not-a-day,1"])
def test_parse_session_log_reports_original_line_number(invalid):
    with pytest.raises(ValueError, match=r"\bline 4\b"):
        parse_session_log(["", " # comment", "good,1,0", invalid])


def test_dedupe_sessions_keeps_last_record_and_sorts_by_day_then_id():
    events = parse_session_log(["b,5,1", "c,2,1", "a,2,0", "b,1,0"])
    assert dedupe_sessions(events) == [events[3], events[2], events[1]]


def test_daily_conversion_counts_include_gaps_and_ignore_out_of_range_sessions():
    events = parse_session_log(["a,0,1", "b,1,1", "c,1,1", "d,2,0", "e,3,", "f,4,1", "g,5,1"])
    assert daily_conversion_counts(events, 1, 4) == [2, 0, 0, 1]
    assert daily_conversion_counts(events, 4, 1) == []


def test_campaign_summary_uses_calendar_days_and_ignores_empty_groups():
    events = parse_session_log(["a,1,1", "b,5,0", "c,5,"])
    assert campaign_summary({"g": events, "empty": []}, 2) == {
        "rate": 0.333,
        "recent": 0,
        "groups": 1,
    }
    assert campaign_summary({"empty": []}, 2) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_top_converting_groups_excludes_empty_groups_and_breaks_ties_by_name():
    groups = {
        "z": [{"converted": True}],
        "empty": [],
        "b": [{"converted": False}],
        "a": [{"converted": True}],
    }
    assert top_converting_groups(groups, 1) == ["a"]
    assert top_converting_groups(groups, 5) == ["a", "z", "b"]


def test_conversion_rate_by_group_sorts_keys_and_distinguishes_empty_groups():
    rates = conversion_rate_by_group({"z": [], "a": [{"converted": False}]})
    assert rates == {"a": 0.0, "z": None}
    assert list(rates) == ["a", "z"]


def test_longest_conversion_streak_resets_on_nonpositive_counts():
    assert longest_conversion_streak([1, 2, 0, 3, -1, 1, 1, 2]) == 3
    assert longest_conversion_streak([0, -1]) == 0
    assert longest_conversion_streak([]) == 0

